require("/luxon/node_modules/@babel/register")({ cwd: "/luxon" });
const { Duration } = require("/luxon/src/luxon.js");

const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];
const accuracies = ["casual","longterm"];
let failures = 0;
const fail = (...a) => { failures++; console.log("FAIL:", ...a); };

// full grid: every ordered pair of units in one duration, several magnitudes/signs
const magnitudes = [1, -1, 3, -3, 0.5, 100];
for (const acc of accuracies) {
  for (const a of units) {
    for (const b of units) {
      for (const m of magnitudes) {
        const dur = Duration.fromObject({ conversionAccuracy: acc, [a]: m, [b]: m * 2 });
        let norm;
        try { norm = dur.normalize(); } catch (e) { fail(`normalize threw ${a}/${b} ${m} (${acc}): ${e.message}`); continue; }
        if (!norm.isValid) { fail(`invalid ${a}/${b} ${m} (${acc})`); continue; }
        const obj = norm.toObject();
        for (const k of Object.keys(obj)) {
          if (typeof obj[k] !== "number" || Number.isNaN(obj[k])) fail(`NaN ${k} in ${JSON.stringify(obj)} from ${a}/${b} ${m} (${acc})`);
        }
        // total value in ms must be preserved by normalize
        const before = dur.as("milliseconds"), after = norm.as("milliseconds");
        if (Math.abs(before - after) > 1e-6 * Math.max(1, Math.abs(before))) {
          fail(`value not preserved ${a}/${b} ${m} (${acc}): ${before} -> ${after}`);
        }
        // every unit pair must be reachable via as()
        for (const u of units) {
          const v = norm.as(u);
          if (typeof v !== "number" || Number.isNaN(v) || !Number.isFinite(v)) fail(`as(${u}) NaN from ${a}/${b} ${m} (${acc})`);
        }
      }
    }
  }
}
console.log(failures === 0 ? "FULL GRID OK" : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);
EOF
